            break
        a = r
        while r < h and any(v != bg for v in grid[r]):
            r += 1
        bands.append((a, r))

    if len(bands) < 2:
        return out

    # Compare the two equal-height patterned bands.
    a, b = bands[0]
    c, d = bands[1]
    if b - a != d - c:
        return out

    height = b - a
    for k in range(height):
        y1, y2 = a + k, c + k
        xs1 = [x for x in range(w) if grid[y1][x] != bg]
        xs2 = [x for x in range(w) if grid[y2][x] != bg]
        if not xs1 or not xs2:
            continue

        e1, e2 = max(xs1), max(xs2)
        if e1 != e2:
            short_y, long_y = (y1, y2) if e1 < e2 else (y2, y1)
            short_end = min(e1, e2)
            long_end = max(e1, e2)

            # In taller repeated motifs, mark the foreground extension itself;
            # otherwise fill the corresponding missing cells on the shorter row.
            target_y = long_y if height > 4 else short_y
            source_y = short_y if target_y == long_y else long_y
            for x in range(short_end + 1, long_end + 1):
                if grid[source_y][x] != bg or grid[target_y][x] == bg:
                    out[target_y][x] = 1
        else:
            # Equal-length rows can still differ in a distinct right-hand block.
            diff = next((x for x in range(w)
                         if grid[y1][x] != grid[y2][x]), w)
            if diff < w:
                tail1 = sum(grid[y1][x] != bg for x in range(diff, w))
                tail2 = sum(grid[y2][x] != bg for x in range(diff, w))
                target_y = y1 if tail1 > tail2 else y2
                for x in range(diff, w):
                    if grid[target_y][x] != bg:
                        out[target_y][x] = 1

